(()=>{const c=document.querySelector('#board'),x=c.getContext('2d'),scoreEl=document.querySelector('#score'),bestEl=document.querySelector('#best'),status=document.querySelector('#status'),overlay=document.querySelector('#overlay');const N=20,S=20;let snake,food,dir,next,score,timer,playing=false,over=false;bestEl.textContent=localStorage.snakeBest||0;function reset(){clearInterval(timer);over=false;overlay.querySelector('h2').textContent='Ready, snake?';overlay.querySelector('p').textContent="Eat the stars. Don't bite your tail.";snake=[{x:9,y:10},{x:8,y:10},{x:7,y:10}];food={x:14,y:10};dir={x:1,y:0};next=dir;score=0;playing=false;scoreEl.textContent='0';status.textContent='Press an arrow key or tap a direction to start.';overlay.style.display='grid';draw()}function draw(){x.fillStyle='#171a2d';x.fillRect(0,0,400,400);x.strokeStyle='#ffffff0b';for(let i=0;i<=N;i++){x.beginPath();x.moveTo(i*S,0);x.lineTo(i*S,400);x.stroke();x.beginPath();x.moveTo(0,i*S);x.lineTo(400,i*S);x.stroke()}x.fillStyle='#ff86b6';x.shadowColor='#ff86b6';x.shadowBlur=13;x.fillRect(food.x*S+5,food.y*S+5,10,10);x.shadowBlur=0;snake.forEach((p,i)=>{x.fillStyle=i?'#9bc749':'#d6ff61';x.fillRect(p.x*S+2,p.y*S+2,S-4,S-4)});const h=snake[0];x.fillStyle='#273041';x.fillRect(h.x*S+6,h.y*S+6,3,3);x.fillRect(h.x*S+13,h.y*S+6,3,3)}function step(){dir=next;const h={x:snake[0].x+dir.x,y:snake[0].y+dir.y};if(h.x<0||h.y<0||h.x>=N||h.y>=N||snake.some(p=>p.x===h.x&&p.y===h.y)){clearInterval(timer);playing=false;over=true;status.textContent='Game over — score '+score+'. Press restart to go again.';overlay.querySelector('h2').textContent='Nice run!';overlay.querySelector('p').textContent='You scored '+score+'. Ready for another?';overlay.style.display='grid';return}snake.unshift(h);if(h.x===food.x&&h.y===food.y){score+=10;scoreEl.textContent=score;if(score>+(localStorage.snakeBest||0)){localStorage.snakeBest=score;bestEl.textContent=score}do{food={x:Math.floor(Math.random()*N),y:Math.floor(Math.random()*N)}}while(snake.some(p=>p.x===food.x&&p.y===food.y))}else snake.pop();draw()}function start(){if(playing)return;if(over)reset();overlay.style.display='none';playing=true;status.textContent='Go! Collect the pink stars.';timer=setInterval(step,115)}function turn(d){if(d.x!==-dir.x||d.y!==-dir.y)next=d;if(!playing)start()}const dirs={ArrowUp:{x:0,y:-1},w:{x:0,y:-1},ArrowDown:{x:0,y:1},s:{x:0,y:1},ArrowLeft:{x:-1,y:0},a:{x:-1,y:0},ArrowRight:{x:1,y:0},d:{x:1,y:0}};document.addEventListener('keydown',e=>{if(dirs[e.key]){e.preventDefault();turn(dirs[e.key])}if(e.key==='Escape'&&playing){clearInterval(timer);playing=false;overlay.querySelector('h2').textContent='Paused';overlay.querySelector('p').textContent='Take a breather, then jump back in.';overlay.style.display='grid'}});document.querySelectorAll('[data-dir]').forEach(b=>b.onclick=()=>turn(({up:{x:0,y:-1},down:{x:0,y:1},left:{x:-1,y:0},right:{x:1,y:0}})[b.dataset.dir]));document.querySelector('#start').onclick=start;document.querySelector('#overlay-start').onclick=start;document.querySelector('#restart').onclick=reset;reset()})();
